function consumptionCard(p){return '<button class="budgetcard '+(p.available!=null&&p.available<0?'exceeded':'')+'" data-action="budget"><div class="between"><h3>Disponible para consumo</h3><span>→</span></div><strong>'+(p.available==null?'Revisar presupuesto':money(p.available))+'</strong>'+cupEquivalent(p.available)+'<small>'+(state.paired?'Presupuesto del Sheet':'Plan inicial propuesto')+': '+(p.budget==null?'por completar':money(p.budget))+' − gastos: '+money(p.spent)+'</small><small>Margen de la partida mensual. Los saldos en efectivo se muestran debajo.</small></button>';}
function budgetDetail(){var p=projection();modal('Tu partida de consumo','<p>Asignado menos gastos del mes, convertidos con la tasa que conserva cada operación. Incluye los gastos pendientes de este teléfono; excluye rechazados, ahorro y fondos.</p><div class="check"><strong>Disponible: '+(p.available==null?'Revisar plan':money(p.available))+'</strong></div>'+p.categoryBudgets.map(function(c){var left=c.budget==null?null:c.budget-c.spent;return '<div class="cart-line"><h3>'+esc(c.name)+'</h3><small>Asignado: '+(c.budget==null?'por completar':money(c.budget))+' · Gastado: '+money(c.spent)+'</small><div class="inline"><span>Disponible</span><strong>'+(left==null?'Revisar':money(left))+'</strong></div></div>';}).join('')+'<div class="notice info">Edita la asignación de cada categoría en Presupuesto, columna C del Sheet, y sincroniza. Los pagos desde fondos reducen el saldo de ese fondo y el efectivo, conservando esta partida de consumo.</div><p class="privacy">Un importe negativo indica que la partida se excedió. Los datos de otros teléfonos se incorporan cuando se sincronizan con el Sheet.</p>');}
