function shop(){if(shoppingMode&&!shoppingChoosing)return shoppingList();return shoppingBanner()+selectionControls()+'<div class="greeting"><div class="eyebrow">Tu compra, bajo control</div><h1>La cesta del hogar</h1><p>Elige, ajusta el precio real y guarda el gasto.</p></div><div class="search"><span>⌕</span><input id="search" type="search" placeholder="Buscar arroz, pollo, jabón…" value="'+esc(search)+'" aria-label="Buscar productos"></div><div class="chips">'+['Todos'].concat(unique(products().map(function(p){return p.category;}))).map(function(c){return '<button class="chip '+(category===c?'active':'')+'" data-category="'+esc(c)+'">'+esc(c)+'</button>';}).join('')+'</div><div class="between"><small id="productCount"></small><button class="link" data-action="expense">Gasto libre ＋</button></div><div class="notice info">Precios de referencia: confirma el importe y la presentación de tu compra. Aquí registras gastos; no se envían pedidos.</div><button class="link" data-action="showMonthly">'+(showMonthly?'Ocultar productos mensuales ya comprados':'Ver también productos mensuales ya comprados')+'</button><div id="products" class="products"></div>'+((state.cart||[]).length&&!multiSelect?'<button class="cartbar" data-action="cart"><span>🛒 &nbsp; Ver mi cesta · '+state.cart.length+' artículo(s)</span><span>'+esc(cartTotals())+' →</span></button>':'');}
